import org.springframework.stereotype.Service;
import static com.yueji.mall.common.persistence.SqlStore.text;

@Service
public class SettlementService {
    private static final ZoneId BEIJING=ZoneId.of("Asia/Shanghai");
    private final SqlStore sql;private final DatabaseTransaction tx;private final IdentityRepository identities;private final IdentityPolicy policy;private final IdempotencyService idempotency;private final AuditRepository audit;private final OutboxService outbox;private final Clock clock;
    public SettlementService(SqlStore sql,DatabaseTransaction tx,IdentityRepository identities,IdentityPolicy policy,IdempotencyService idempotency,AuditRepository audit,OutboxService outbox,Clock clock){this.sql=sql;this.tx=tx;this.identities=identities;this.policy=policy;this.idempotency=idempotency;this.audit=audit;this.outbox=outbox;this.clock=clock;}
    public PageData<SettlementView> financeList(Actor actor,String shop,String status,LocalDate date,PageQuery page){policy.require(actor,"finance.settlement.read");if(page.sort()!=null)throw new BusinessException(ErrorCode.PARAM_INVALID);String where=" WHERE 1=1";var args=new ArrayList<Object>();if(shop!=null){new ApiId(shop);where+=" AND shop_id=?";args.add(shop);}if(status!=null){if(!Set.of("DRAFT","APPROVED","PAID","REJECTED").contains(status))throw new BusinessException(ErrorCode.PARAM_INVALID);where+=" AND status=?";args.add(status);}if(date!=null){where+=" AND period_date=?";args.add(date);}return page(where,args,page,false,false);}
    public PageData<SettlementView> merchantList(Actor actor,String shop,String status,PageQuery page){policy.requireShop(actor,shop,"MERCHANT","shop.settlement.read");if(page.sort()!=null)throw new BusinessException(ErrorCode.PARAM_INVALID);String where=" WHERE shop_id=?";var args=new ArrayList<Object>();args.add(shop);if(status!=null){if(!Set.of("DRAFT","APPROVED","PAID","REJECTED").contains(status))throw new BusinessException(ErrorCode.PARAM_INVALID);where+=" AND status=?";args.add(status);}return page(where,args,page,false,true);}
    public SettlementView financeView(Actor actor,String id){policy.require(actor,"finance.settlement.read");new ApiId(id);return view(id,true,false);}
    public SettlementView merchantView(Actor actor,String shop,String id){policy.requireShop(actor,shop,"MERCHANT","shop.settlement.read");new ApiId(id);var row=sql.required("SELECT id FROM settlement WHERE id=? AND shop_id=?",id,shop);return view(text(row,"id"),true,true);}
    private PageData<SettlementView> page(String where,List<Object> base,PageQuery page,boolean details,boolean mask){var args=new ArrayList<Object>(base);long total=sql.count("SELECT COUNT(*) FROM settlement"+where,args.toArray());args.add(page.pageSize());args.add(page.offset());var ids=sql.rows("SELECT id FROM settlement"+where+" ORDER BY period_date DESC,id DESC LIMIT ? OFFSET ?",args.toArray()).stream().map(r->text(r,"id")).toList();return new PageData<>(ids.stream().map(id->view(id,details,mask)).toList(),page.page(),page.pageSize(),total);}
    public SettlementView create(Actor actor,SettlementInput input,String key,String trace){
        if(!input.periodDate().isBefore(LocalDate.now(clock.withZone(BEIJING))))throw new BusinessException(ErrorCode.SETTLEMENT_BLOCKED);
        String shop=input.shopId().value();boolean[] created={false};try {
            var result=tx.run(()->{identities.shareCommerceAnchor();identities.lockUser(actor.userId());policy.require(actor,"finance.settlement.create");sql.required("SELECT id FROM shop WHERE id=?",shop);return idempotency.execute(actor,"API-59",key,List.of(shop,input.periodDate()),"settlement",shop+":"+input.periodDate(),SettlementView.class,()->{
                var current=sql.one("SELECT * FROM settlement WHERE shop_id=? AND period_date=?",shop,input.periodDate());if(current.isPresent()&&!"REJECTED".equals(text(current.get(),"status")))return view(text(current.get(),"id"),true,false);
                var carry=sql.rows("SELECT s.id,s.payable_amount FROM settlement s WHERE s.shop_id=? AND s.status='DRAFT' AND s.payable_amount<=0 AND s.period_date<? ORDER BY s.period_date,s.id",shop,input.periodDate());
                var candidateIds=eligibleIds(shop,input.periodDate());var allIds=new TreeSet<String>(Comparator.comparing((String value)->new BigInteger(value)));allIds.addAll(candidateIds);
                // Approved, unassigned adjustments also reference orders; lock those orders before finance rows.
                allIds.addAll(sql.rows("SELECT order_id FROM settlement_adjustment WHERE shop_id=? AND status='APPROVED' AND target_settlement_id IS NULL ORDER BY order_id,id",shop).stream().map(r->text(r,"order_id")).toList());
                for(var c:carry)allIds.addAll(sql.rows("SELECT order_id FROM settlement_item WHERE settlement_id=? ORDER BY order_id",c.get("id")).stream().map(r->text(r,"order_id")).toList());
                if(current.isPresent()&&"REJECTED".equals(text(current.get(),"status")))allIds.addAll(sql.rows("SELECT order_id FROM settlement_item WHERE settlement_id=? ORDER BY order_id",current.get().get("id")).stream().map(r->text(r,"order_id")).toList());
                lockOrders(allIds);lockItems(allIds);lockRelated(allIds);var statement=sql.one("SELECT * FROM settlement WHERE shop_id=? AND period_date=? FOR UPDATE",shop,input.periodDate());String settlementId;
                if(statement.isEmpty())settlementId=sql.insert("INSERT INTO settlement(settlement_no,shop_id,period_date,status,created_by) VALUES(?,?,?,'DRAFT',?)","S"+UUID.randomUUID().toString().replace("-",""),shop,input.periodDate(),actor.userId());
                else settlementId=text(statement.get(),"id");
                if(statement.isPresent()){
                    var old=statement.get();if(!"REJECTED".equals(text(old,"status")))return view(settlementId,true,false);
                    sql.update("DELETE FROM settlement_item WHERE settlement_id=?",settlementId);sql.update("UPDATE settlement SET status='DRAFT',gross_amount=0,refund_amount=0,fee_amount=0,adjustment_amount=0,payable_amount=0,created_by=?,approved_by=NULL,approved_at=NULL,paid_by=NULL,paid_at=NULL,mock_payout_no=NULL,version=version+1,updated_at=UTC_TIMESTAMP(3) WHERE id=?",actor.userId(),settlementId);
                }
                // 余额不足的未出款单及经批准的调整原子移入本期；旧单保留 REJECTED 记录。
                for(var old:carry){String oldId=text(old,"id");var oldItems=sql.rows("SELECT * FROM settlement_item WHERE settlement_id=? ORDER BY order_id FOR UPDATE",oldId);sql.update("DELETE FROM settlement_item WHERE settlement_id=?",oldId);
                    for(var line:oldItems)sql.insert("INSERT INTO settlement_item(settlement_id,order_id,goods_amount,refund_amount,net_amount,fee_rate,fee_amount,payable_amount) VALUES(?,?,?,?,?,?,?,?)",settlementId,line.get("order_id"),line.get("goods_amount"),line.get("refund_amount"),line.get("net_amount"),line.get("fee_rate"),line.get("fee_amount"),line.get("payable_amount"));
                    sql.update("UPDATE settlement_adjustment SET target_settlement_id=? WHERE target_settlement_id=? AND status='APPROVED'",settlementId,oldId);sql.update("UPDATE settlement SET status='REJECTED',version=version+1,updated_at=UTC_TIMESTAMP(3) WHERE id=? AND status='DRAFT'",oldId);audit.appendReason(actor.userId(),"settlement.carry_forward","settlement",oldId,shop,"SUCCESS","余额结转至"+input.periodDate());
                }
                for(String orderId:candidateIds){if(!eligible(orderId,cutoff(input.periodDate()),settlementId))continue;var o=sql.required("SELECT * FROM trade_order WHERE id=?",orderId);BigDecimal gross=(BigDecimal)o.get("goods_amount"),refund=(BigDecimal)o.get("refunded_amount"),net=gross.subtract(refund).setScale(2);if(net.signum()<=0)continue;BigDecimal fee=net.multiply(new BigDecimal("0.03")).setScale(2,RoundingMode.HALF_UP),payable=net.subtract(fee);sql.insert("INSERT INTO settlement_item(settlement_id,order_id,goods_amount,refund_amount,net_amount,fee_rate,fee_amount,payable_amount) VALUES(?,?,?,?,?,0.0300,?,?)",settlementId,orderId,gross,refund,net,fee,payable);}
                var adjustments=sql.rows("SELECT * FROM settlement_adjustment WHERE shop_id=? AND status='APPROVED' AND target_settlement_id IS NULL ORDER BY id FOR UPDATE",shop);for(var adjustment:adjustments){if(!"RESOLVED".equals(text(sql.required("SELECT status FROM reconciliation_issue WHERE id=?",adjustment.get("issue_id")),"status")))continue;sql.update("UPDATE settlement_adjustment SET target_settlement_id=?,updated_at=UTC_TIMESTAMP(3) WHERE id=? AND target_settlement_id IS NULL",settlementId,adjustment.get("id"));}
                if(sql.count("SELECT COUNT(*) FROM settlement_item WHERE settlement_id=?",settlementId)==0&&sql.count("SELECT COUNT(*) FROM settlement_adjustment WHERE target_settlement_id=? AND status='APPROVED'",settlementId)==0)throw new BusinessException(ErrorCode.SETTLEMENT_BLOCKED);
                recalculate(settlementId);audit.append(actor.userId(),"settlement.create","settlement",settlementId,shop,"SUCCESS");created[0]=true;return view(settlementId,true,false);
            });});return result;
        } catch(DuplicateKeyException duplicate){return findByShopDate(shop,input.periodDate());}
    }
    public SettlementView decide(Actor actor,String id,DecisionInput input,String key,String trace){new ApiId(id);policy.require(actor,"finance.settlement.approve");var refs=settlementReferences(id);return tx.run(()->{identities.shareCommerceAnchor();identities.lockUser(actor.userId());policy.require(actor,"finance.settlement.approve");lockOrders(refs);lockItems(refs);lockRelated(refs);return idempotency.execute(actor,"API-60",key,List.of(id,input.approved(),input.note(),input.version()),"settlement",id,SettlementView.class,()->{
            var s=sql.required("SELECT * FROM settlement WHERE id=? FOR UPDATE",id);if(((Number)s.get("version")).longValue()!=input.version())throw new BusinessException(ErrorCode.VERSION_CONFLICT);if(Objects.equals(s.get("created_by").toString(),actor.userId()))throw new BusinessException(ErrorCode.ACCESS_DENIED);
            if("APPROVED".equals(text(s,"status"))&&input.approved())return view(id,true,false);if("REJECTED".equals(text(s,"status"))&&!input.approved())return view(id,true,false);if(!"DRAFT".equals(text(s,"status")))throw new BusinessException(ErrorCode.STATE_CONFLICT);
            if(input.approved()){revalidate(id);if(((BigDecimal)s.get("payable_amount")).signum()<=0)throw new BusinessException(ErrorCode.SETTLEMENT_BLOCKED);sql.update("UPDATE settlement SET status='APPROVED',approved_by=?,approved_at=UTC_TIMESTAMP(3),version=version+1,updated_at=UTC_TIMESTAMP(3) WHERE id=? AND status='DRAFT'",actor.userId(),id);audit.appendReason(actor.userId(),"settlement.approve","settlement",id,text(s,"shop_id"),"SUCCESS",input.note().trim());}
            else {sql.update("DELETE FROM settlement_item WHERE settlement_id=?",id);sql.update("UPDATE settlement_adjustment SET target_settlement_id=NULL WHERE target_settlement_id=? AND status='APPROVED'",id);sql.update("UPDATE settlement SET status='REJECTED',approved_by=?,approved_at=UTC_TIMESTAMP(3),version=version+1,updated_at=UTC_TIMESTAMP(3) WHERE id=?",actor.userId(),id);audit.appendReason(actor.userId(),"settlement.reject","settlement",id,text(s,"shop_id"),"SUCCESS",input.note().trim());}
            return view(id,true,false);
        });});}
    public SettlementView payout(Actor actor,String id,PayoutInput input,String key,String trace){new ApiId(id);policy.require(actor,"finance.settlement.payout");var refs=settlementReferences(id);return tx.run(()->{identities.shareCommerceAnchor();identities.lockUser(actor.userId());policy.require(actor,"finance.settlement.payout");lockOrders(refs);lockItems(refs);lockRelated(refs);return idempotency.execute(actor,"API-61",key,List.of(id,input.version()),"settlement",id,SettlementView.class,()->{
            var s=sql.required("SELECT * FROM settlement WHERE id=? FOR UPDATE",id);if(((Number)s.get("version")).longValue()!=input.version())throw new BusinessException(ErrorCode.VERSION_CONFLICT);if("PAID".equals(text(s,"status")))return view(id,true,false);if(!"APPROVED".equals(text(s,"status"))||((BigDecimal)s.get("payable_amount")).signum()<=0)throw new BusinessException(ErrorCode.SETTLEMENT_BLOCKED);revalidate(id);
            String voucher="MOCK-"+UUID.randomUUID().toString().replace("-","");if(sql.update("UPDATE settlement SET status='PAID',paid_by=?,paid_at=UTC_TIMESTAMP(3),mock_payout_no=?,version=version+1,updated_at=UTC_TIMESTAMP(3) WHERE id=? AND status='APPROVED'",actor.userId(),voucher,id)!=1)throw new BusinessException(ErrorCode.STATE_CONFLICT);
            sql.update("UPDATE settlement_adjustment SET status='APPLIED',updated_at=UTC_TIMESTAMP(3) WHERE target_settlement_id=? AND status='APPROVED'",id);outbox.factFor("settlement","SettlementPaid",id,Map.of("settlementId",id,"shopId",text(s,"shop_id"),"mockPayoutNo",voucher),trace);audit.appendReason(actor.userId(),"settlement.mock_payout","settlement",id,text(s,"shop_id"),"SUCCESS","仅模拟出款");return view(id,true,false);
        });});}
    public PageData<AdjustmentView> adjustments(Actor actor,String shop,String status,PageQuery page){policy.require(actor,"finance.adjustment.manage");if(page.sort()!=null||status!=null&&!Set.of("PENDING","APPROVED","APPLIED").contains(status))throw new BusinessException(ErrorCode.PARAM_INVALID);String where=" WHERE 1=1";var args=new ArrayList<Object>();if(shop!=null){new ApiId(shop);where+=" AND shop_id=?";args.add(shop);}if(status!=null){where+=" AND status=?";args.add(status);}long count=sql.count("SELECT COUNT(*) FROM settlement_adjustment"+where,args.toArray());args.add(page.pageSize());args.add(page.offset());var ids=sql.rows("SELECT id FROM settlement_adjustment"+where+" ORDER BY created_at DESC,id DESC LIMIT ? OFFSET ?",args.toArray()).stream().map(r->text(r,"id")).toList();return new PageData<>(ids.stream().map(this::adjustmentView).toList(),page.page(),page.pageSize(),count);}
    public AdjustmentView createAdjustment(Actor actor,AdjustmentInput input,String trace){String original=input.originalSettlementId().value(),order=input.orderId().value(),issue=input.issueId().value();return tx.run(()->{identities.shareCommerceAnchor();identities.lockUser(actor.userId());policy.require(actor,"finance.adjustment.manage");sql.required("SELECT id FROM trade_order WHERE id=? FOR UPDATE",order);sql.rows("SELECT id FROM order_item WHERE order_id=? ORDER BY id FOR UPDATE",order);lockRelated(Set.of(order));var s=sql.required("SELECT * FROM settlement WHERE id=? FOR UPDATE",original);if(!"PAID".equals(text(s,"status"))||sql.count("SELECT COUNT(*) FROM settlement_item WHERE settlement_id=? AND order_id=?",original,order)==0||!text(s,"shop_id").equals(text(sql.required("SELECT shop_id FROM trade_order WHERE id=?",order),"shop_id")))throw new BusinessException(ErrorCode.STATE_CONFLICT);
            var evidence=sql.required("SELECT * FROM reconciliation_issue WHERE id=? FOR UPDATE",issue);if(!"RESOLVED".equals(text(evidence,"status")))throw new BusinessException(ErrorCode.SETTLEMENT_BLOCKED);boolean linked=Objects.equals(evidence.get("order_id")==null?null:evidence.get("order_id").toString(),order)||evidence.get("payment_id")!=null&&sql.count("SELECT COUNT(*) FROM payment WHERE id=? AND order_id=?",evidence.get("payment_id"),order)>0||evidence.get("refund_id")!=null&&sql.count("SELECT COUNT(*) FROM refund r JOIN payment p ON p.id=r.payment_id WHERE r.id=? AND p.order_id=?",evidence.get("refund_id"),order)>0;if(!linked)throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);
            BigDecimal expected=expectedAdjustment(original,order);if(expected.signum()==0||expected.compareTo(input.amount().value())!=0)throw new BusinessException(ErrorCode.SETTLEMENT_BLOCKED);
            String id=sql.insert("INSERT INTO settlement_adjustment(shop_id,original_settlement_id,order_id,issue_id,amount,reason,created_by) VALUES(?,?,?,?,?,?,?)",s.get("shop_id"),original,order,issue,input.amount().value(),input.reason().trim(),actor.userId());audit.appendReason(actor.userId(),"settlement.adjustment.create","settlement_adjustment",id,text(s,"shop_id"),"SUCCESS",issue);return adjustmentView(id);});}
    public AdjustmentView approveAdjustment(Actor actor,String id,AdjustmentDecisionInput input){new ApiId(id);policy.require(actor,"finance.adjustment.manage");var pre=sql.required("SELECT order_id,original_settlement_id FROM settlement_adjustment WHERE id=?",id);String order=text(pre,"order_id");return tx.run(()->{identities.shareCommerceAnchor();identities.lockUser(actor.userId());policy.require(actor,"finance.adjustment.manage");sql.required("SELECT id FROM trade_order WHERE id=? FOR UPDATE",order);sql.rows("SELECT id FROM order_item WHERE order_id=? ORDER BY id FOR UPDATE",order);lockRelated(Set.of(order));var s=sql.required("SELECT * FROM settlement WHERE id=? FOR UPDATE",pre.get("original_settlement_id"));var a=sql.required("SELECT * FROM settlement_adjustment WHERE id=? FOR UPDATE",id);if("APPROVED".equals(text(a,"status"))||"APPLIED".equals(text(a,"status")))return adjustmentView(id);if(!"PENDING".equals(text(a,"status"))||Objects.equals(a.get("created_by").toString(),actor.userId()))throw new BusinessException(ErrorCode.ACCESS_DENIED);if(!"PAID".equals(text(s,"status"))||expectedAdjustment(text(s,"id"),order).compareTo((BigDecimal)a.get("amount"))!=0)throw new BusinessException(ErrorCode.SETTLEMENT_BLOCKED);var issue=sql.required("SELECT status FROM reconciliation_issue WHERE id=? FOR UPDATE",a.get("issue_id"));if(!"RESOLVED".equals(text(issue,"status")))throw new BusinessException(ErrorCode.SETTLEMENT_BLOCKED);
            sql.update("UPDATE settlement_adjustment SET status='APPROVED',approved_by=?,reason=LEFT(CONCAT(reason,' | 审核：',?),500),updated_at=UTC_TIMESTAMP(3) WHERE id=?",actor.userId(),input.note().trim(),id);audit.appendReason(actor.userId(),"settlement.adjustment.approve","settlement_adjustment",id,text(s,"shop_id"),"SUCCESS",input.note().trim());return adjustmentView(id);});}
    private List<String> eligibleIds(String shop,LocalDate period){Instant cutoff=cutoff(period);Timestamp t=Timestamp.from(cutoff);return sql.rows("SELECT o.id FROM trade_order o WHERE o.shop_id=? AND o.status='COMPLETED' AND o.completed_at<DATE_SUB(?,INTERVAL 7 DAY) AND NOT EXISTS(SELECT 1 FROM after_sale a WHERE a.order_id=o.id AND a.status IN ('REQUESTED','APPROVED','RETURNING','RECEIVED','REFUNDING')) AND NOT EXISTS(SELECT 1 FROM refund r JOIN payment p ON p.id=r.payment_id WHERE p.order_id=o.id AND r.status IN ('CREATED','PROCESSING','FAILED')) AND NOT EXISTS(SELECT 1 FROM reconciliation_issue x WHERE x.status='OPEN' AND (x.order_id=o.id OR x.payment_id IN(SELECT p.id FROM payment p WHERE p.order_id=o.id) OR x.refund_id IN(SELECT r.id FROM refund r JOIN payment p ON p.id=r.payment_id WHERE p.order_id=o.id))) AND NOT EXISTS(SELECT 1 FROM settlement_item si JOIN settlement s ON s.id=si.settlement_id WHERE si.order_id=o.id AND s.status IN ('DRAFT','APPROVED','PAID')) AND NOT EXISTS(SELECT 1 FROM settlement_adjustment sa WHERE sa.order_id=o.id AND sa.status='PENDING') ORDER BY o.id",shop,t).stream().map(r->text(r,"id")).toList();}
    private boolean eligible(String order,Instant cutoff,String currentSettlement){Timestamp t=Timestamp.from(cutoff);return sql.count("SELECT COUNT(*) FROM trade_order o WHERE o.id=? AND o.status='COMPLETED' AND o.completed_at<DATE_SUB(?,INTERVAL 7 DAY) AND NOT EXISTS(SELECT 1 FROM after_sale a WHERE a.order_id=o.id AND a.status IN ('REQUESTED','APPROVED','RETURNING','RECEIVED','REFUNDING')) AND NOT EXISTS(SELECT 1 FROM refund r JOIN payment p ON p.id=r.payment_id WHERE p.order_id=o.id AND r.status IN ('CREATED','PROCESSING','FAILED')) AND NOT EXISTS(SELECT 1 FROM reconciliation_issue x WHERE x.status='OPEN' AND (x.order_id=o.id OR x.payment_id IN(SELECT p.id FROM payment p WHERE p.order_id=o.id) OR x.refund_id IN(SELECT r.id FROM refund r JOIN payment p ON p.id=r.payment_id WHERE p.order_id=o.id))) AND NOT EXISTS(SELECT 1 FROM settlement_item si JOIN settlement s ON s.id=si.settlement_id WHERE si.order_id=o.id AND s.id<>? AND s.status IN ('DRAFT','APPROVED','PAID')) AND NOT EXISTS(SELECT 1 FROM settlement_adjustment sa WHERE sa.order_id=o.id AND sa.status='PENDING')",order,t,currentSettlement)>0;}
    private void revalidate(String id){var s=sql.required("SELECT * FROM settlement WHERE id=?",id);var items=sql.rows("SELECT * FROM settlement_item WHERE settlement_id=? ORDER BY order_id",id);BigDecimal gross=BigDecimal.ZERO.setScale(2),refund=BigDecimal.ZERO.setScale(2),fee=BigDecimal.ZERO.setScale(2);Instant cutoff=cutoff(date(s.get("period_date")));
        for(var item:items){String order=text(item,"order_id");if(!eligible(order,cutoff,id))throw new BusinessException(ErrorCode.SETTLEMENT_BLOCKED);var o=sql.required("SELECT * FROM trade_order WHERE id=?",order);BigDecimal currentGross=(BigDecimal)o.get("goods_amount"),currentRefund=(BigDecimal)o.get("refunded_amount"),net=currentGross.subtract(currentRefund).setScale(2),currentFee=net.multiply((BigDecimal)item.get("fee_rate")).setScale(2,RoundingMode.HALF_UP);if(currentGross.compareTo((BigDecimal)item.get("goods_amount"))!=0||currentRefund.compareTo((BigDecimal)item.get("refund_amount"))!=0||net.compareTo((BigDecimal)item.get("net_amount"))!=0||currentFee.compareTo((BigDecimal)item.get("fee_amount"))!=0)throw new BusinessException(ErrorCode.SETTLEMENT_BLOCKED);gross=gross.add(currentGross);refund=refund.add(currentRefund);fee=fee.add(currentFee);}
        BigDecimal adjustment=sql.required("SELECT COALESCE(SUM(amount),0.00) total FROM settlement_adjustment WHERE target_settlement_id=? AND status='APPROVED'",id).get("total") instanceof BigDecimal x?x:BigDecimal.ZERO.setScale(2);if(gross.compareTo((BigDecimal)s.get("gross_amount"))!=0||refund.compareTo((BigDecimal)s.get("refund_amount"))!=0||fee.compareTo((BigDecimal)s.get("fee_amount"))!=0||adjustment.compareTo((BigDecimal)s.get("adjustment_amount"))!=0||gross.subtract(refund).subtract(fee).add(adjustment).compareTo((BigDecimal)s.get("payable_amount"))!=0)throw new BusinessException(ErrorCode.SETTLEMENT_BLOCKED);
    }
    private BigDecimal expectedAdjustment(String original,String order){var s=sql.required("SELECT * FROM settlement WHERE id=?",original);var orig=sql.required("SELECT * FROM settlement_item WHERE settlement_id=? AND order_id=?",original,order);var o=sql.required("SELECT * FROM trade_order WHERE id=?",order);BigDecimal net=((BigDecimal)o.get("goods_amount")).subtract((BigDecimal)o.get("refunded_amount")).setScale(2);BigDecimal fee=net.multiply((BigDecimal)orig.get("fee_rate")).setScale(2,RoundingMode.HALF_UP);BigDecimal payable=net.subtract(fee);BigDecimal prior=(BigDecimal)sql.required("SELECT COALESCE(SUM(amount),0.00) total FROM settlement_adjustment WHERE order_id=? AND status IN ('APPROVED','APPLIED')",order).get("total");return payable.subtract((BigDecimal)orig.get("payable_amount")).subtract(prior).setScale(2);}
    private List<String> settlementReferences(String id){var ids=new TreeSet<String>(Comparator.comparing((String value)->new BigInteger(value)));ids.addAll(sql.rows("SELECT order_id FROM settlement_item WHERE settlement_id=? ORDER BY order_id",id).stream().map(r->text(r,"order_id")).toList());ids.addAll(sql.rows("SELECT order_id FROM settlement_adjustment WHERE target_settlement_id=? ORDER BY order_id",id).stream().map(r->text(r,"order_id")).toList());return List.copyOf(ids);}
    private void lockOrders(Collection<String> ids){if(ids.isEmpty())return;var sorted=ids.stream().distinct().sorted(Comparator.comparing((String value)->new BigInteger(value))).toList();sql.rows("SELECT id FROM trade_order WHERE id IN ("+marks(sorted.size())+") ORDER BY id FOR UPDATE",sorted.toArray());}
    private void lockItems(Collection<String> ids){if(ids.isEmpty())return;var sorted=ids.stream().distinct().sorted(Comparator.comparing((String value)->new BigInteger(value))).toList();sql.rows("SELECT id FROM order_item WHERE order_id IN ("+marks(sorted.size())+") ORDER BY id FOR UPDATE",sorted.toArray());}
    private void lockRelated(Collection<String> ids){if(ids.isEmpty())return;var sorted=ids.stream().distinct().sorted(Comparator.comparing((String value)->new BigInteger(value))).toList();String m=marks(sorted.size());Object[] args=sorted.toArray();sql.rows("SELECT id FROM after_sale WHERE order_id IN ("+m+") ORDER BY order_id,id FOR UPDATE",args);sql.rows("SELECT r.id FROM refund r JOIN payment p ON p.id=r.payment_id WHERE p.order_id IN ("+m+") ORDER BY r.id FOR UPDATE",args);sql.rows("SELECT x.id FROM reconciliation_issue x WHERE x.order_id IN ("+m+") OR x.payment_id IN(SELECT p.id FROM payment p WHERE p.order_id IN ("+m+")) OR x.refund_id IN(SELECT r.id FROM refund r JOIN payment p ON p.id=r.payment_id WHERE p.order_id IN ("+m+")) ORDER BY x.id FOR UPDATE",concat(args,args,args));sql.rows("SELECT id FROM settlement_item WHERE order_id IN ("+m+") ORDER BY order_id,id FOR UPDATE",args);sql.rows("SELECT id FROM settlement_adjustment WHERE order_id IN ("+m+") ORDER BY order_id,id FOR UPDATE",args);}
    private Object[] concat(Object[]... arrays){return Arrays.stream(arrays).flatMap(Arrays::stream).toArray();}private String marks(int n){return String.join(",",Collections.nCopies(n,"?"));}
    private void recalculate(String id){var sum=sql.required("SELECT COALESCE(SUM(goods_amount),0.00) gross,COALESCE(SUM(refund_amount),0.00) refunds,COALESCE(SUM(fee_amount),0.00) fees FROM settlement_item WHERE settlement_id=?",id);var adj=sql.required("SELECT COALESCE(SUM(amount),0.00) total FROM settlement_adjustment WHERE target_settlement_id=? AND status='APPROVED'",id);BigDecimal gross=(BigDecimal)sum.get("gross"),refund=(BigDecimal)sum.get("refunds"),fee=(BigDecimal)sum.get("fees"),adjust=(BigDecimal)adj.get("total"),payable=gross.subtract(refund).subtract(fee).add(adjust);sql.update("UPDATE settlement SET gross_amount=?,refund_amount=?,fee_amount=?,adjustment_amount=?,payable_amount=?,version=version+1,updated_at=UTC_TIMESTAMP(3) WHERE id=?",gross,refund,fee,adjust,payable,id);}
    private Instant cutoff(LocalDate date){return date.plusDays(1).atStartOfDay(BEIJING).toInstant();}
    private LocalDate date(Object value){return value instanceof java.sql.Date d?d.toLocalDate():(LocalDate)value;}
    private SettlementView findByShopDate(String shop,LocalDate date){String id=sql.required("SELECT id FROM settlement WHERE shop_id=? AND period_date=?",shop,date).get("id").toString();return view(id,true,false);}
    private SettlementView view(String id,boolean details,boolean mask){var s=sql.required("SELECT * FROM settlement WHERE id=?",id);LocalDate date=date(s.get("period_date"));List<ItemView> items=null;List<AdjustmentView> adjustments=null;if(details){items=sql.rows("SELECT * FROM settlement_item WHERE settlement_id=? ORDER BY order_id",id).stream().map(r->new ItemView(new ApiId(text(r,"order_id")),money(r,"goods_amount"),money(r,"refund_amount"),money(r,"net_amount"),money(r,"fee_amount"),money(r,"payable_amount"))).toList();adjustments=sql.rows("SELECT id FROM settlement_adjustment WHERE target_settlement_id=? ORDER BY id",id).stream().map(r->adjustmentView(text(r,"id"),mask)).toList();}
        return new SettlementView(new ApiId(id),text(s,"settlement_no"),new ApiId(text(s,"shop_id")),date,text(s,"status"),money(s,"gross_amount"),money(s,"refund_amount"),money(s,"fee_amount"),money(s,"adjustment_amount"),money(s,"payable_amount"),mask?null:new ApiId(text(s,"created_by")),mask||s.get("approved_by")==null?null:new ApiId(text(s,"approved_by")),RowValues.instant(s.get("paid_at")),(String)s.get("mock_payout_no"),((Number)s.get("version")).longValue(),items,adjustments);}
    private ApiMoney money(Map<String,Object> row,String column){return new ApiMoney((BigDecimal)row.get(column));}
    private AdjustmentView adjustmentView(String id){return adjustmentView(id,false);}
    private AdjustmentView adjustmentView(String id,boolean mask){var a=sql.required("SELECT * FROM settlement_adjustment WHERE id=?",id);return new AdjustmentView(new ApiId(id),new ApiId(text(a,"original_settlement_id")),new ApiId(text(a,"order_id")),new ApiId(text(a,"issue_id")),money(a,"amount"),text(a,"reason"),text(a,"status"),mask?null:new ApiId(text(a,"created_by")),mask||a.get("approved_by")==null?null:new ApiId(text(a,"approved_by")),a.get("target_settlement_id")==null?null:new ApiId(text(a,"target_settlement_id")));}
}
